      first start;
      then if ((io_0) and ((not previousIo0))) {
        first start;
        then assign counter := counter + 1;
        then assign previousIo0 := io_0;
      } else {
        first start;
        then assign previousIo0 := io_0;
      }
    }
    out attribute serial_0_trigger : Boolean = ((io_0) and ((not previousIo0)));
